"""Locate a fastText engine that is byte-for-byte the authors' algorithm and
expose train()/test().

Ladder (assumption A14):
  1. importable `fasttext` module (fasttext-wheel 0.9.2 = prebuilt binary
     wheel of facebookresearch/fastText v0.9.2, i.e. the same src/ C++ code
     as the cloned repo, only compiled for this platform);
  2. pip install fasttext-wheel (prebuilt, no compiler needed);
  3. native build of the cloned repo (make / pip install ./repo) if a POSIX
     toolchain exists;
  4. last resort: re-implement with torch.nn.EmbeddingBag (authors'
     FastTextEmbeddingBag example) -> would downgrade the verdict to
     partially_reproduced.

No hyperparameter is rewritten here: train() forwards kwargs verbatim.
"""

import importlib
import os
import shutil
import subprocess
import sys
import time

PROVENANCE = {"engine": None, "detail": None, "verdict_ceiling": "reproduced"}


def _try_import():
    try:
        ft = importlib.import_module("fasttext")
        PROVENANCE["engine"] = "fasttext python binding"
        PROVENANCE["detail"] = f"module fasttext importable at {getattr(ft, '__file__', '?')}"
        return ft
    except Exception as e:
        print(f"  [engine] import fasttext failed: {type(e).__name__}: {e}")
        return None


def _pip_install(pkg):
    print(f"  [engine] pip install {pkg} ...")
    try:
        t0 = time.time()
        subprocess.run([sys.executable, "-m", "pip", "install", pkg],
                       check=True, capture_output=True, text=True, timeout=600)
        print(f"  [engine] installed {pkg} in {time.time()-t0:.1f}s")
        return True
    except Exception as e:
        print(f"  [engine] pip install {pkg} failed: {e}")
        return False


def _native_build():
    """Build the cloned authors' repo if a POSIX toolchain is available."""
    if not (shutil.which("make") and (shutil.which("g++") or shutil.which("clang++"))):
        return None
    repo = os.path.join(os.path.dirname(os.path.abspath(__file__)), "repo")
    try:
        subprocess.run(["make"], cwd=repo, check=True, capture_output=True, text=True, timeout=900)
        binpath = os.path.join(repo, "fasttext")
        if os.path.isfile(binpath):
            PROVENANCE["engine"] = "authors' native build (repo/src C++, ./fasttext)"
            PROVENANCE["detail"] = f"make in {repo}"
            return ("native", binpath)
    except Exception as e:
        print(f"  [engine] native build failed: {e}")
    return None


def get_engine():
    ft = _try_import()
    if ft is not None:
        return ft
    for pkg in ("fasttext-wheel", "fasttext"):
        if _pip_install(pkg):
            ft = _try_import()
            if ft is not None:
                return ft
    nat = _native_build()
    if nat is not None:
        return nat[0]
    # last resort: re-implementation (downgrades verdict)
    try:
        import fasttext_torch_fallback  # noqa: F401
        PROVENANCE["engine"] = "EmbeddingBag re-implementation"
        PROVENANCE["verdict_ceiling"] = "partially_reproduced"
        return "fallback"
    except Exception as e:
        raise RuntimeError(
            "No fastText engine available: tried import, pip fasttext-wheel/fasttext, "
            f"native build; EmbeddingBag fallback unavailable ({e})"
        )


def train(ft, input_path, output_path, **kw):
    """Train with the authors' supervised algorithm; kwargs forwarded verbatim.
    Returns (model_path, seconds)."""
    t0 = time.time()
    if isinstance(ft, str) and ft == "native":
        args = ["supervised", "-input", input_path, "-output", output_path]
        for k, v in kw.items():
            args += [f"-{k}", str(v)]
        subprocess.run([ft_bin, *args], check=True)
    else:
        ft.train_supervised(input=input_path, output=output_path, **kw)
    secs = time.time() - t0
    model_path = output_path + ".bin"
    if not os.path.isfile(model_path):
        raise RuntimeError(f"training produced no model at {model_path}")
    return model_path, secs


ft_bin = None


def test(ft, model_path, test_path):
    """Authors' evaluation path (src/meter.cc): returns (N, P@1, R@1).
    Every AG News line carries exactly one label, so P@1 == accuracy."""
    if isinstance(ft, str) and ft == "native":
        out = subprocess.run([ft_bin, "test", model_path, test_path],
                             check=True, capture_output=True, text=True)
        parts = out.stdout.replace("\t", " ").split()
        n = int(parts[0])
        p1 = float(parts[2])
        return n, p1, p1
    model = ft.load_model(model_path)
    return model.test(test_path)

